        "title": "10人小作坊做到年产值2亿：一枚鱼钩，他卖了全球65国",
        "hook": "同样是鱼钩，别人论斤卖，他偏要论枚卖——就这一个改法，把10个人的小作坊做成了年产值2亿。",
        "story": {
          "setup": "2001年，24岁的占志波辞掉教师\"铁饭碗\"，接手父亲在鄱阳湖边的鱼钩小作坊：只有10个工人，鱼钩论斤卖，利润薄得像刀片。",
          "conflict": "一次国际渔具展，他被国外产品震惊——同样一枚鱼钩，人家按枚标价、包装考究，自家只能论斤甩卖。订单来了，产能又跟不上，最熟练工人一天只做3万枚。",
          "turn": "他拿出全部30万积蓄加十几万借款买下日本淘汰的成型机，带着师傅啃了3个月修好；随后从论斤卖改成论枚卖、从代工转到自主品牌BKK，单枚零售价十几元。",
          "open": "占志波已经落地鄱阳。那枚论枚卖的鱼钩背后，站着2001年那个只有10个人的作坊，和一个不肯认输的年轻人。"
        },
        "facts": [
          "起点为2001年鄱阳湖边10人家庭作坊，鱼钩论斤卖，最熟练工人一天做3万枚",
          "占志波用30万积蓄+十几万借款买日本淘汰成型机，带师傅3个月修好",
          "从论斤卖改论枚卖、从OEM代工转自主品牌BKK，单枚零售价平均十几元",
          "如今年产鱼钩近30亿枚、年产值超2亿元，BKK注册全球65国、49项专利，为全球第三大鱼钩生产企业之一"
        ],
        "titles": [
          "论斤卖改论枚卖，他把鱼钩卖到全球第三",
          "10人小作坊到2亿：只改了一件事",
          "制造业老板都该懂的\"价值差\"生意经"
        ],
        "cover": "10人作坊 / 论斤卖改论枚 / 年产值2亿",
        "script": [
          {
            "t": "0-5秒",
            "label": "钩子",
            "text": "2001年，鄱阳湖边一个只有10个工人的鱼钩作坊。"
          },
          {
            "t": "5-27秒",
            "label": "铺垫",
            "text": "24岁的占志波辞掉了教师的铁饭碗。他要靠一枚小小的鱼钩，撑起一整个厂。这间鱼钩作坊是父亲传下来的。鱼钩论斤卖，最熟练的工人一天只能做3万枚，利润薄得像刀片。占志波每天醒来第一个问题是：怎么活下去。那年他刚辞掉教职，父亲没拦他。"
          },
          {
            "t": "27-43秒",
            "label": "冲突",
            "text": "转机来自一次国际渔具展。他被展台上外国产品的标价牌震住了：同样一枚鱼钩，人家按枚标价、包装考究，自家只能论斤甩卖。订单来了，产能却跟不上，最熟练的工人一天也就3万枚。"
          },
          {
            "t": "43-62秒",
            "label": "反转",
            "text": "他看中一台日本淘汰的鱼钩成型机，用掉全部30万积蓄、再借贷十几万买下。机器运回鄱阳就三天两头出毛病，眼看积蓄要打水漂。没学过一天机械的他，带着几位师傅扎进车间，夜里看书学机械。三个月后，机器转起来了。"
          },
          {
            "t": "62-82秒",
            "label": "细节",
            "text": "接下来几年，他组建研发团队，做出适配各类鱼钩的标准化成型机，日本、欧美的代工单接了一茬又一茬。可占志波心里一直不踏实——代工做得再好，定价权是别人的。他决定启动自主品牌BKK，从论斤卖改成论枚卖，单枚卖到十几元。"
          },
          {
            "t": "82-99秒",
            "label": "结果",
            "text": "今天，这家企业年产鱼钩近30亿枚、年产值超2亿元，BKK商标在全球65个国家注册，拿到49项全球专利，是全球第三大鱼钩生产企业之一。一条从湖边出发的小路，走到了65个国家。"
          },
          {
            "t": "99-119秒",
            "label": "收尾",
            "text": "鄱阳湖边那个只有10个人的作坊里，如今是机器声压过了湖风。2001年那个辞掉教书的24岁年轻人大概没想过，自家做的鱼钩有一天会论枚卖，还挂上自己的牌子。这中间靠的不是运气，是一台旧机器和几年没停过的手艺。"
          }
        ],
