            "t": "83-103秒",
            "label": "结果",
            "text": "一车1000多斤菜，换回1000元。钱不算多，可对一个妻子患病、家里负债、正被关在里面的人来说，这是一张从泥里递过来的网。他该承担的那10天，一分也没少；这10天里他唯一能做的，就是等着那车菜有个着落。"
