        "heat": "抖音热榜 #6 · 百度热搜 #8/#22 · 全网辟谣",
        "title": "「朴树去世」是假消息，哥哥一句「不可能」破局",
        "hook": "一条模糊的「朴树去世」配文疯传，越转越像真事——直到哥哥濮石出面：不可能。一句最朴素的否认，把一场谣言按了暂停键。",
        "story": {
          "setup": "有网友发布模糊配文引发「朴树去世」猜测，相关说法在转发链里被不断强化、曲解为事实错误；朴树哥哥濮石直接回应「不可能」。",
          "conflict": "语义模糊的信息，在转发里被一层层「加戏」，最后变成大家都当真的讹传——这是网络谣言最典型的传播路径。",
          "turn": "哥哥一句即时、明确的否认，比任何平台公告都快，也提醒我们：遇到名人「被去世」，先等家属或本人说话，别急着转。",
          "open": "三个字把一条消息按停了。群里最先说话的那个人，后来又发了一句道歉，然后被新消息顶上去了。"
        },
        "facts": [
          "网友模糊配文引发「朴树去世」猜测并在转发中被曲解",
          "朴树哥哥濮石直接回应「不可能」予以否认",
          "该事件呈现网络谣言从模糊到「坐实」的典型传播路径",
          "本人/家属即时澄清是阻断谣言最快的方式"
        ],
        "titles": [
          "朴树去世是假消息，哥哥：不可能",
          "一句「不可能」，按停一场谣言",
          "名人被去世，别急着转"
        ],
        "cover": "朴树 / 哥哥辟谣 / 温暖反转",
        "script": [
          {
            "t": "0-5秒",
            "label": "钩子",
            "text": "「朴树去世」这四个字，被一句「不可能」打了回去。"
          },
          {
            "t": "5-22秒",
            "label": "铺垫",
            "text": "起因是一段很模糊的配文。有人发出来，配上几句含含糊糊的话，读的人开始猜；猜出来的版本被转发，转发的时候又被添上一句，添到最后，像一件已经发生过的事。截图里其实什么都没写清楚。"
          },
          {
            "t": "22-42秒",
            "label": "冲突",
            "text": "这类消息的走法几乎是固定的：一句话在几百次转发里被加戏，从「听说」变成「好像」，再变成「已经走了」。等到所有人都在说同一句话，它看起来就像事实。而最后被反复添加的，往往是最初那位发布者根本没说过的东西。"
          },
          {
            "t": "42-57秒",
            "label": "反转",
            "text": "打破它的，是朴树的哥哥濮石。三个字：不可能。没有任何铺垫，没有任何解释，就是最直接的否认。这比任何一份平台公告都快——公告要考虑措辞、要走流程，家属不需要。"
          },
          {
            "t": "57-74秒",
            "label": "细节",
            "text": "家里人的一句话为什么这么快？因为它最直接，也不承担「要不要负责」的顾虑。消息在往上滚的时候，是没有人负责的；一条「不可能」发出来，链条就断了——它不需要说服谁，只需要说对。"
          },
          {
            "t": "74-93秒",
            "label": "结果",
            "text": "有网友的模糊配文引发了「朴树去世」的猜测，并在转发中被一步步曲解；濮石一句「不可能」，把这条路按停了。到 11 月 13 日，这条消息在多个平台上都被标成了假消息，那个最初的模糊配文，也一起被推回了原处。"
          },
          {
            "t": "93-104秒",
            "label": "收尾",
            "text": "聊天群里安静下来，最后一条消息停在「不可能」三个字上。发消息的人后来又打了一句「对不起」，发完就被新的消息顶上去了。"
          }
        ],
