            "text": "不烧油，不载人。11月11日，我国自主研发的“轻骑兵”中小型太阳能无人机在西北某机场成功首飞。机身长3.2米，翼展8米，太阳能是唯一动力源——不上油，也不载人。它要顶掉的不是新鲜感，是一件耗人力的活。"
