            "text": "央行用一个专栏回答了“钱去哪了”。11月11日，中国人民银行发布《2026年第三季度中国货币政策执行报告》。三季度末人民币存款余额349.45万亿元，同比增长7.5%。钱一分没少，只是换了个地方待着。报告专门辟出一个专栏，回答那个被问了很多年的问题。"
